<script setup lang="ts">
import NewProductDialog from '../../features/preview/components/NewProductDialog.vue';
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
import { computed, reactive, ref, watch } from 'vue';
import { ElMessage } from 'element-plus/es/components/message/index.mjs';
import { usePreview, copy, type Product, type ShopOrder, type Refund } from '../../features/preview/usePreviewStore';
import { dateOf, money } from '../../features/workbench/types';
import PageHeading from '../../features/preview/components/PageHeading.vue';
import TableFooter from '../../features/preview/components/TableFooter.vue';
import ProductThumbnail from '../../features/workbench/components/ProductThumbnail.vue';
import OrderDetailDialog from '../../features/workbench/components/OrderDetailDialog.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
const newProductOpen=ref(false);
const props=defineProps<{view:string}>(); const s=usePreview();
const titles:Record<string,string>={customers:'客户管理',products:'商品管理',orders:'订单管理',payments:'支付记录',shipments:'物流管理',refunds:'退款售后',inventory:'库存流水'};
const descriptions:Record<string,string>={customers:'查看与维护店铺客户资料，收货资料修改不影响已有订单。',products:'维护商品、上下架和可用库存。',orders:'查询订单，处理付款、发货、取消与退款申请。',payments:'查看订单支付与退款结果。',shipments:'查看包裹信息，更新物流状态。',refunds:'根据售后状态审核申请、登记收货与完成退款。',inventory:'查看商品入库、订单预占与售后回库记录。'};
const search=ref(''),status=ref(''),page=ref(1),dialog=ref(false),error=ref(''),editingId=ref<number|null>(null),mode=ref('');
const form=reactive({name:'',phone:'',address:'',note:'',variant:'',price:0,stock:0,active:true,productId:0,customerId:0,quantity:1,extra:'',adjust:1,reason:''});
watch(()=>props.view,()=>{search.value='';status.value='';page.value=1;dialog.value=false;newProductOpen.value=false;});watch([search,status],()=>page.value=1);
const productGroups=computed(()=>[...new Set(s.products.value.map(p=>p.groupId))].map(id=>{const variants=s.products.value.filter(p=>p.groupId===id).sort((a,b)=>a.id-b.id);return {...variants[0],id,variants,stock:variants.reduce((n,p)=>n+p.stock,0),reserved:variants.reduce((n,p)=>n+p.reserved,0),active:variants.some(p=>p.active)};}));
const productGroupId=ref<number|null>(null),productOpen=ref(false),newVariantGroup=ref<number|null>(null);
const selectedProduct=computed(()=>productGroups.value.find(p=>p.id===productGroupId.value));
function showProduct(id:number){productGroupId.value=id;productOpen.value=true;}
function addVariant(){const parent=selectedProduct.value;if(!parent)return;open('product');newVariantGroup.value=parent.id;form.name=parent.name;form.price=parent.price;form.active=parent.active;}

const pRows=computed(()=>productGroups.value.filter(p=>`${p.name} ${p.variants.map(v=>v.variant).join(' ')}`.includes(search.value.trim())&&(!status.value||String(p.active)===status.value)));
const cRows=computed(()=>s.customers.value.filter(c=>`${c.name} ${c.phone}`.includes(search.value.trim())));
const oRows=computed(()=>s.orders.value.filter(o=>`${o.number} ${o.customer} ${o.product}`.includes(search.value.trim())&&(!status.value||o.stage===status.value)));
const shipRows=computed(()=>oRows.value.filter(o=>['SHIPPED','DELIVERED'].includes(o.stage)));
const payRows=computed(()=>s.payments.value.filter(p=>`${getOrder(p.orderId)?.number} ${getOrder(p.orderId)?.customer}`.includes(search.value.trim())&&(!status.value||p.status===status.value)));
const refundRows=computed(()=>s.refunds.value.filter(r=>`${getOrder(r.orderId)?.number} ${r.reason}`.includes(search.value.trim())&&(!status.value||r.status===status.value)));
const invRows=computed(()=>s.inventory.value.filter(i=>`${getProduct(i.productId)?.name} ${i.reason}`.includes(search.value.trim())));
const count=computed(()=>({products:pRows.value,customers:cRows.value,orders:oRows.value,shipments:shipRows.value,payments:payRows.value,refunds:refundRows.value,inventory:invRows.value}[props.view]?.length||0));
const options=computed(()=>props.view==='products'?[['true','在售'],['false','已下架']]:props.view==='payments'?[['支付成功','支付成功'],['已退款','已退款']]:props.view==='refunds'?Object.entries(refundLabels):['orders','shipments'].includes(props.view)?Object.entries(orderLabels):[]);
const orderLabels:Record<string,string>={UNPAID:'待付款',PAID:'待发货',SHIPPED:'运输中',DELIVERED:'已签收',CANCELLED:'已取消',REFUNDING:'售后处理中',REFUNDED:'已退款'};
const refundLabels:Record<string,string>={REQUESTED:'待审核',APPROVED:'已同意',REJECTED:'已拒绝',RECEIVED:'已收货',COMPLETED:'已退款'};
const dialogTitle=computed(()=>({customer:editingId.value?'编辑客户':'新增客户',product:editingId.value?'编辑商品':'新增商品',order:'创建订单',stock:'调整可用库存',ship:'登记发货',refund:'申请全额退款',cancel:'确认取消订单',pay:'确认支付',deliver:'确认签收',approve:'同意退款申请',reject:'拒绝退款申请',receive:'登记退货收货',complete:'完成退款'}[mode.value]||'确认操作'));
function getOrder(id:number){return s.orders.value.find(o=>o.id===id);}function getProduct(id:number){return s.products.value.find(p=>p.id===id);}
function slice<T>(rows:T[]){return rows.slice((page.value-1)*8,page.value*8);}
function open(kind:string,id:number|null=null){newVariantGroup.value=null;mode.value=kind;editingId.value=id;error.value='';Object.assign(form,{name:'',phone:'',address:'',note:'',variant:'',price:129,stock:0,active:true,productId:0,customerId:0,quantity:1,extra:'',adjust:1,reason:''});if(kind==='product'&&id)Object.assign(form,copy(getProduct(id)));if(kind==='customer'&&id)Object.assign(form,copy(s.customers.value.find(c=>c.id===id)));dialog.value=true;}
function toggleProduct(p:Product){const active=!p.active;s.products.value.filter(v=>v.groupId===p.groupId).forEach(v=>v.active=active);ElMessage.success(active?'商品已上架':'商品已下架');}
function removeProduct(p:Product){const ids=s.products.value.filter(v=>v.groupId===p.groupId).map(v=>v.id);if(s.orders.value.some(o=>ids.includes(o.productId))||s.inventory.value.some(i=>ids.includes(i.productId))){ElMessage.warning('商品已有订单或库存流水，请使用下架保留记录');return;}s.products.value=s.products.value.filter(x=>x.groupId!==p.groupId);ElMessage.success('商品已删除');}
function removeCustomer(id:number){if(s.orders.value.some(o=>o.customerId===id)||s.wb.conversations.value.some(c=>c.customerId===id)){ElMessage.warning('客户已有关联记录，保留资料供查阅');return;}s.customers.value=s.customers.value.filter(c=>c.id!==id);ElMessage.success('客户已删除');}
function submit(){error.value='';try{
  if(mode.value==='product'){if(!form.name.trim()||!form.variant.trim()||!Number.isFinite(form.price)||form.price<=0||!Number.isInteger(form.stock)||form.stock<0)throw new Error('请填写商品名称、规格、正确的价格与非负整数库存。');if(editingId.value){const p=getProduct(editingId.value)!;if(s.products.value.some(v=>v.id!==p.id&&v.groupId===p.groupId&&v.variant===form.variant.trim()))throw new Error('该规格已存在。');s.products.value.filter(v=>v.groupId===p.groupId).forEach(v=>v.name=form.name.trim());p.variant=form.variant.trim();p.price=Math.round(form.price*100)/100;p.active=form.active;/* Inventory changes have their own traceable action. */}else{const id=Date.now();if(newVariantGroup.value&&s.products.value.some(v=>v.groupId===newVariantGroup.value&&v.variant===form.variant.trim()))throw new Error('该规格已存在。');s.products.value.unshift({id,groupId:newVariantGroup.value||id,name:form.name.trim(),variant:form.variant.trim(),price:Math.round(form.price*100)/100,stock:0,reserved:0,active:form.active,thumbnail:newVariantGroup.value?s.products.value.find(v=>v.groupId===newVariantGroup.value)!.thumbnail:'shirt',imageUrl:newVariantGroup.value?s.products.value.find(v=>v.groupId===newVariantGroup.value)?.imageUrl:undefined});if(form.stock)s.stock(s.products.value[0],form.stock,'商品初始入库');}}
  else if(mode.value==='customer'){if(!form.name.trim()||!form.phone.trim()||!form.address.trim())throw new Error('请填写客户姓名、联系电话和地址。');const payload={name:form.name.trim(),phone:form.phone.trim(),address:form.address.trim(),note:form.note.trim()};if(editingId.value)Object.assign(s.customers.value.find(c=>c.id===editingId.value)!,payload);else s.customers.value.unshift({id:Date.now(),...payload});}
  else if(mode.value==='order')s.createOrder(form.customerId,form.productId,form.quantity);
  else if(mode.value==='stock'){if(!Number.isInteger(form.adjust)||!form.adjust||!form.reason.trim())throw new Error('请填写非零整数调整量与原因。');s.stock(getProduct(editingId.value!)!,form.adjust,form.reason.trim());}
  else if(['approve','reject','receive','complete'].includes(mode.value))s.refundAction(editingId.value!,mode.value,form.extra);
  else s.orderAction(editingId.value!,mode.value,form.extra);
  dialog.value=false;ElMessage.success('操作已完成');
}catch(e){error.value=(e as Error).message;}}
const detail=ref<ShopOrder|null>(null),detailOpen=ref(false);function show(o:ShopOrder){detail.value=o;detailOpen.value=true;}
</script>
<template><div class="pv-page"><PageHeading :title="titles[view]" :description="descriptions[view]" eyebrow="电商管理"/>
<div v-if="view==='products'" class="pv-mini-stats"><div><span>商品总数</span><strong>{{productGroups.length}}</strong></div><div><span>在售商品</span><strong>{{productGroups.filter(p=>p.active).length}}</strong></div><div><span>可用库存</span><strong>{{s.products.value.reduce((n,p)=>n+p.stock,0)}}</strong></div></div>
<div class="pv-card"><div class="pv-filters"><div class="pv-search"><Icon name="Search"/><input v-model="search" :placeholder="view==='products'?'搜索商品或规格':view==='customers'?'搜索客户或电话':'搜索订单、客户或说明'" aria-label="搜索电商记录"/></div><PreviewSelect v-if="options.length" v-model="status" aria-label="状态筛选"><option value="">全部状态</option><option v-for="option in options" :key="option[0]" :value="option[0]">{{option[1]}}</option></PreviewSelect><div v-if="['products','orders'].includes(view)" class="pv-card-actions pv-filter-end"><button v-if="['products','orders'].includes(view)" class="wb-btn primary" @click="view==='products'?newProductOpen=true:open('order')"><Icon name="Plus"/>{{view==='products'?'新增商品':'创建订单'}}</button></div></div>
<div class="pv-table-scroll">
<table v-if="view==='products'" class="pv-table"><thead><tr><th>商品</th><th>售价</th><th>可用 / 预占库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in slice(pRows)" :key="p.id"><td><div class="pv-product"><ProductThumbnail :kind="p.thumbnail" :src="p.imageUrl"/><div><strong>{{p.name}}</strong><small>{{p.variants.length}} 种规格</small></div></div></td><td class="pv-number">{{money(p.variants[0].price)}}</td><td><button class="wb-text-button" @click="showProduct(p.id)">{{p.stock}} <span class="pv-muted"> / {{p.reserved}}</span></button><small v-for="v in p.variants" :key="v.id">{{v.variant}}：{{v.stock}} 件</small></td><td><span class="pv-tag" :class="p.active?'green':''">{{p.active?'在售':'已下架'}}</span></td><td><div class="pv-row-actions"><button @click="showProduct(p.id)">商品详情</button><button @click="toggleProduct(p)">{{p.active?'下架':'上架'}}</button><button class="danger" @click="removeProduct(p)">删除</button></div></td></tr></tbody></table>
<table v-else-if="view==='customers'" class="pv-table"><thead><tr><th>客户</th><th>联系电话</th><th>收货资料</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="c in slice(cRows)" :key="c.id"><td><div class="pv-customer"><span class="wb-avatar blue">{{c.name[0]}}</span><div><strong>{{c.name}}</strong><small>#{{c.id}}</small></div></div></td><td>{{c.phone}}</td><td>{{c.address}}</td><td>{{c.note||'—'}}</td><td><div class="pv-row-actions"><button @click="open('customer',c.id)">编辑</button><button class="danger" @click="removeCustomer(c.id)">删除</button></div></td></tr></tbody></table>
<table v-else-if="view==='orders'" class="pv-table"><thead><tr><th>订单 / 商品</th><th>客户</th><th>金额 / 数量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in slice(oRows)" :key="o.id"><td><strong>{{o.number}}</strong><small>{{o.product}} · {{o.variant}}</small></td><td>{{o.customer}}</td><td>{{money(o.amount)}}<small>共 {{o.quantity}} 件</small></td><td><span class="pv-tag" :class="o.stage==='REFUNDING'?'amber':o.stage==='DELIVERED'?'green':'blue'">{{orderLabels[o.stage]}}</span></td><td><div class="pv-row-actions"><button @click="show(o)">详情</button><button v-if="o.stage==='UNPAID'" @click="open('pay',o.id)">支付</button><button v-if="o.stage==='PAID'" @click="open('ship',o.id)">发货</button><button v-if="['UNPAID','PAID'].includes(o.stage)" @click="open('cancel',o.id)">取消订单</button><button v-if="['PAID','SHIPPED','DELIVERED'].includes(o.stage)" @click="open('refund',o.id)">申请退款</button></div></td></tr></tbody></table>
<table v-else-if="view==='payments'" class="pv-table"><thead><tr><th>支付记录</th><th>关联订单</th><th>支付金额</th><th>结果</th><th>支付时间</th><th>操作</th></tr></thead><tbody><tr v-for="p in slice(payRows)" :key="p.id"><td><strong>PAY{{p.id}}</strong></td><td>{{getOrder(p.orderId)?.number}}<small>{{getOrder(p.orderId)?.customer}}</small></td><td>{{money(p.amount)}}</td><td><span class="pv-tag" :class="p.status==='支付成功'?'green':''">{{p.status}}</span></td><td>{{dateOf(p.createdAt)}}</td><td><button class="wb-text-button" @click="show(getOrder(p.orderId)!)">查看订单</button></td></tr></tbody></table>
<table v-else-if="view==='shipments'" class="pv-table"><thead><tr><th>物流单号</th><th>订单 / 客户</th><th>商品</th><th>物流状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in slice(shipRows)" :key="o.id"><td><strong>{{o.tracking}}</strong><small>{{o.carrier}}</small></td><td>{{o.number}}<small>{{o.customer}}</small></td><td>{{o.product}} × {{o.quantity}}</td><td><span class="pv-tag" :class="o.stage==='DELIVERED'?'green':'blue'">{{orderLabels[o.stage]}}</span></td><td><div class="pv-row-actions"><button @click="show(o)">查看详情</button><button v-if="o.stage==='SHIPPED'" @click="open('deliver',o.id)">确认签收</button></div></td></tr></tbody></table>
<table v-else-if="view==='refunds'" class="pv-table"><thead><tr><th>售后记录</th><th>关联订单</th><th>退款金额 / 原因</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in slice(refundRows)" :key="r.id"><td><strong>RF{{r.id}}</strong><small>{{dateOf(r.createdAt)}}</small></td><td>{{getOrder(r.orderId)?.number}}<small>{{getOrder(r.orderId)?.customer}}</small></td><td>{{money(r.amount)}}<small>{{r.reason}}</small></td><td><span class="pv-tag" :class="r.status==='REQUESTED'?'amber':r.status==='COMPLETED'?'green':''">{{refundLabels[r.status]}}</span></td><td><div class="pv-row-actions"><button @click="show(getOrder(r.orderId)!)">订单详情</button><template v-if="r.status==='REQUESTED'"><button @click="open('approve',r.id)">同意</button><button class="danger" @click="open('reject',r.id)">拒绝</button></template><button v-if="r.status==='APPROVED'&&r.original!=='PAID'" @click="open('receive',r.id)">登记收货</button><button v-if="r.status==='RECEIVED'||(r.status==='APPROVED'&&r.original==='PAID')" @click="open('complete',r.id)">完成退款</button></div></td></tr></tbody></table>
<table v-else class="pv-table"><thead><tr><th>商品</th><th>变动数量</th><th>变动后可用库存</th><th>原因</th><th>操作人 / 时间</th></tr></thead><tbody><tr v-for="i in slice(invRows)" :key="i.id"><td><strong>{{getProduct(i.productId)?.name}}</strong><small>{{getProduct(i.productId)?.variant}}</small></td><td><span :class="i.change>0?'pv-positive':'pv-negative'">{{i.change>0?'+':''}}{{i.change}}</span></td><td>{{i.after}}</td><td>{{i.reason}}</td><td>{{i.actor}}<small>{{dateOf(i.createdAt)}}</small></td></tr></tbody></table>
<div v-if="!count" class="pv-empty"><Icon name="ShoppingBag"/><strong>{{search||status?'没有符合条件的记录':'这里还没有记录'}}</strong><span>{{view==='refunds'?'可以从订单管理发起退款申请':'调整筛选条件，或先创建相关数据'}}</span></div></div><TableFooter v-model:page="page" :total="count"/></div>
<NewProductDialog v-model="newProductOpen" @saved="search='';status='';page=1"/><el-dialog append-to-body v-model="dialog" :title="dialogTitle" width="540px" class="wb-dialog" align-center><form id="pv-commerce-form" class="pv-form" @submit.prevent="submit">
<template v-if="mode==='customer'"><label>客户姓名<input v-model="form.name" maxlength="50" required/></label><label>联系电话<input v-model="form.phone" maxlength="30" required/></label><label>收货地址<textarea v-model="form.address" rows="2" maxlength="300" required/></label><label>备注<textarea v-model="form.note" rows="2" maxlength="300"/><small>由客服手动填写，全店客服可查看和修改。</small></label></template>
<template v-else-if="mode==='product'"><label>商品名称<input v-model="form.name" :readonly="!!newVariantGroup" maxlength="100" required/></label><label>商品规格<input v-model="form.variant" maxlength="100" required/></label><div class="pv-form-grid"><label>售价（元）<input v-model.number="form.price" type="number" min="0.01" step="0.01" required/></label><label v-if="!editingId">初始库存<input v-model.number="form.stock" type="number" min="0" step="1" required/></label></div><label class="pv-check"><input v-model="form.active" type="checkbox"/>上架销售</label><p v-if="editingId" class="pv-muted">库存请通过列表中的「调整库存」修改，便于保留流水。</p></template>
<template v-else-if="mode==='order'"><label>客户<PreviewSelect v-model="form.customerId" aria-label="客户" required><option :value="0" disabled>请选择客户</option><option v-for="c in s.customers.value" :key="c.id" :value="c.id">{{c.name}}</option></PreviewSelect></label><label>商品<PreviewSelect v-model="form.productId" aria-label="商品" required><option :value="0" disabled>请选择商品</option><option v-for="p in s.products.value.filter(p=>p.active)" :key="p.id" :value="p.id">{{p.name}} · {{p.variant}} · 库存 {{p.stock}}</option></PreviewSelect></label><label>数量<input v-model.number="form.quantity" type="number" min="1" step="1" required/></label><p class="pv-notice">创建后预占库存，付款后可发货。</p></template>
<template v-else-if="mode==='stock'"><p>{{getProduct(editingId!)?.name}} · 当前可用 {{getProduct(editingId!)?.stock}}</p><label>调整数量<input v-model.number="form.adjust" type="number" step="1" required/><small>正数增加，负数减少</small></label><label>调整原因<input v-model="form.reason" maxlength="100" required/></label></template>
<template v-else-if="['ship','refund','receive'].includes(mode)"><p class="pv-notice">{{mode==='ship'?'为本订单登记顺丰发货信息。':mode==='refund'?'沿用现有电商流程，按订单实付金额申请全额退款。':'核实退回商品后登记收货，商品将回到可用库存。'}}</p><label>{{mode==='refund'?'退款原因':mode==='receive'?'退货快递单号':'快递单号'}}<input v-model="form.extra" maxlength="200" required/></label></template>
<template v-else><p class="pv-notice">{{mode==='pay'?'确认支付后将生成支付记录。':mode==='cancel'?'取消将释放预占库存；已支付订单同时退回全额款项。':mode==='deliver'?'确认后将订单物流状态更新为已签收。':mode==='approve'?'确认同意此退款申请？已发货订单仍需登记退货收货。':mode==='reject'?'拒绝后恢复申请前的订单状态。':'确认退款完成后，将同步更新支付和订单结果。'}}</p></template><p v-if="error" class="wb-form-error" role="alert">{{error}}</p></form><template #footer><button class="wb-btn" @click="dialog=false">取消</button><button class="wb-btn primary" form="pv-commerce-form" type="submit">确认{{mode==='customer'||mode==='product'?'保存':''}}</button></template></el-dialog><OrderDetailDialog v-model="detailOpen" :order="detail"/>
<el-drawer v-model="productOpen" :title="selectedProduct?.name||'商品详情'" size="min(760px, 100vw)" class="wb-history-drawer pv-product-drawer" append-to-body><template v-if="selectedProduct"><div class="pv-product-detail-head"><ProductThumbnail :kind="selectedProduct.thumbnail" :src="selectedProduct.imageUrl"/><div><h3>{{selectedProduct.name}}</h3><p>{{money(selectedProduct.variants[0].price)}} · 共 {{selectedProduct.stock}} 件可用库存</p></div><button class="wb-btn primary" @click="addVariant">新增规格</button></div><div class="pv-table-scroll"><table class="pv-table"><thead><tr><th>规格</th><th>售价</th><th>可用库存</th><th>预占</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="v in selectedProduct.variants" :key="v.id"><td>{{v.variant}}</td><td>{{money(v.price)}}</td><td>{{v.stock}}</td><td>{{v.reserved}}</td><td>{{v.active?'在售':'已下架'}}</td><td><div class="pv-row-actions"><button @click="open('product',v.id)">编辑</button><button @click="open('stock',v.id)">调整库存</button></div></td></tr></tbody></table></div></template></el-drawer></div></template>
